// app/channels/web/static/htmx.min.js - Minimal self-contained local interaction engine
(function() {
  document.addEventListener('DOMContentLoaded', function() {
    document.body.addEventListener('click', async function(e) {
      var btn = e.target.closest('[hx-post]');
      if (!btn) return;
      e.preventDefault();
      var url = btn.getAttribute('hx-post');
      var targetSel = btn.getAttribute('hx-target');
      var swap = btn.getAttribute('hx-swap') || 'outerHTML';
      var confirmMsg = btn.getAttribute('hx-confirm');
      if (confirmMsg && !window.confirm(confirmMsg)) return;

      var headers = { 'X-Requested-With': 'XMLHttpRequest' };
      var rootHeaders = document.body.getAttribute('hx-headers');
      if (rootHeaders) {
        try { Object.assign(headers, JSON.parse(rootHeaders)); } catch (_) {}
      }

      var form = btn.closest('form');
      var body = null;
      if (form) {
        body = new FormData(form);
      } else {
        var card = btn.closest('.match-card') || btn.parentElement;
        if (card) {
          body = new FormData();
          var inputs = card.querySelectorAll('input, select, textarea');
          inputs.forEach(function(inp) {
            if (inp.name) {
              if (inp.type === 'checkbox') {
                if (inp.checked) body.append(inp.name, inp.value || 'true');
              } else {
                body.append(inp.name, inp.value);
              }
            }
          });
        }
      }

      btn.disabled = true;
      try {
        var resp = await fetch(url, {
          method: 'POST',
          headers: headers,
          body: body
        });
        var html = await resp.text();
        var target = targetSel ? document.querySelector(targetSel) : btn;
        if (target) {
          if (swap === 'outerHTML') {
            target.outerHTML = html;
          } else {
            target.innerHTML = html;
          }
        }
      } catch (err) {
        console.error(err);
        btn.disabled = false;
      }
    });
  });
})();
